//! Runtime bytecode and ABI of `contracts/Runner.sol`, injected via `eth_simulateV1` state
//! overrides: at the simulated trader for legs the pool pays out directly, and at a router
//! address for real swaps against a Uniswap V2 style pair.
//!
//! Compiled with solc 0.8.30:
//! `solc --bin-runtime --via-ir --optimize --optimize-runs 200 --no-cbor-metadata
//! --evm-version berlin Runner.sol`
//!
//! Berlin, because the analyzer also runs on blocks before London and Shanghai.

use alloy::sol;

pub(super) const RUNNER_BYTECODE: &[u8] = &alloy::primitives::hex!(
    ""
);

sol! {
    #[derive(Debug, PartialEq, Eq)]
    struct LegResult {
        uint256 bought;
        bool transferOk;
        uint256 transferSent;
        uint256 transferReceived;
        uint256 transferGas;
        bool sellOk;
        uint256 sellSent;
        uint256 sellArrived;
        uint256 sellGas;
        bytes transferRevert;
        bytes sellRevert;
    }

    function record(address token) external;
    function legs(address token, address pool, address wallet) external returns (LegResult memory r);

    #[derive(Debug, PartialEq, Eq)]
    struct BuyResult {
        bool swapOk;
        uint256 expected;
        uint256 bought;
        bool forwardOk;
        uint256 forwardSent;
        uint256 forwardReceived;
        uint256 forwardGas;
        bytes swapRevert;
        bytes forwardRevert;
    }

    #[derive(Debug, PartialEq, Eq)]
    struct SellResult {
        bool transferOk;
        uint256 sent;
        uint256 arrived;
        bool swapOk;
        uint256 gas;
        bytes transferRevert;
        bytes swapRevert;
    }

    function buy(address token, address pair, address weth, address receiver) external payable returns (BuyResult memory r);
    function sell(address token, address pair) external returns (SellResult memory r);

    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}
